def _w(x):
    """'뫼(산) / 섬' → 단어마다 한 줄, 뜻풀이는 단어 아래 작은 글씨"""
    return '<br>'.join(re.sub(r'^(.*?)\((.*)\)$', r'\1<small>(\2)</small>', t.strip()) for t in x.split('/')) if x else ''


