# ---------------------------------------------------------------- [20~21] 2020 9월 11~12
PSG_20 = ('<p class="hd"><b>[20~21]</b> 다음 글을 읽고 물음에 답하시오. <small>(원문 요약)</small></p>'
          '<p>(1) 영수는 서울에서/서울에 산다. (2) 민수는 방에서/*방에 공부하고 있다. (3) 학교에서 체육 대회를 열었다. (1)은 \'에\', \'에서\'가 모두 가능한데 (2)는 \'에서\'만 가능한 이유는 무엇이고, (3)의 \'에서\'가 주격 조사로 쓰일 수 있는 이유는 무엇일까?</p>'
          '<p>\'에\'는 [지점], \'에서\'는 [공간](행위가 이루어지거나 일이 발생하는 곳)의 의미를 준다. 같은 장소도 지점으로 인식되면 \'에\', 공간으로 인식되면 \'에서\'가 쓰인다. (2)에서 \'방에\'가 안 되는 이유는 \'공부\'라는 행위가 이루어지는 장소이므로 공간의 의미가 필요하기 때문이다. 이 차이는 \'에서\'의 중세 형태 \'에셔\'의 형성 과정에서 나온다.</p>'
          '<p>중세 국어에서 부사격 조사 \'애/에/예, 익/의\'와 \'이시다\'(현대 \'있다\')의 활용형 \'이셔\'가 결합하여 줄어서 \'애셔/에셔/예셔, 익셔/의셔\'가 되었다. 본래 \'이시다\'를 포함하므로 어떤 공간 속에 있음을 전제하여 앞 명사를 공간으로 인식하게 한다. 그런데 이 새 형태가 쓰일 자리에 \'애/에/예, 익/의\'가 쓰이는 경우도 많았다. 이는 \'애/에/예, 익/의\'가 현대 \'에\'와 \'에서\'의 쓰임을 모두 지녔음을 뜻한다.</p>'
          '<p>\'애셔/에셔/예셔, 익셔/의셔\' 앞의 명사가 구성원으로 이루어진 공간·집단이면 그 속 구성원의 행위를 공간·집단의 행위로 표현할 수 있어 중세에 주격 조사로도 쓰였다. 현대 \'에서\'로 이어져 (3)에서 확인된다. 현대 \'에서\'가 주격 조사로 쓰일 때는 앞에 공간·집단을 나타내는 명사가 오며 유정 명사는 올 수 없다. 부사격 \'에\'에 \'서\'가 붙은 \'에서\'가 주격으로 쓰인 것처럼 부사격 \'께\'에 \'서\'가 붙은 \'께서\'도 주격으로 쓰인다. \'께서\'의 중세 형태 부사격 \'긔셔\'도 \'긔\'(= \'ᄉ긔\')와 \'셔\'가 결합해 형성되었고, 근대 국어를 거쳐 주격 조사로 변화해 현대 \'께서\'로 이어졌다. 중세 \'에셔\', 현대 \'에서\'와 달리 중세 \'긔셔\', 현대 \'께서\'는 높임의 유정 명사 뒤에 나타난다.</p>')

add('N-044', 'Ⅱ-D', '중세 국어의 격 조사', '상', S % '2020학년도 9월 모의평가 11번', p('윗글의 내용과 일치하는 것은?'),
    ['중세 국어 \'에\' 앞의 명사는 공간의 의미를 나타낼 수 있었다.', '현대 국어 \'에\' 앞에 붙을 수 있는 명사는 \'에서\' 앞에 붙을 수 없다.', '중세 국어 \'애/에/예\'는 \'익/의\'와 달리 주격 조사로 쓰일 수 있었다.', '현대 국어 \'에서\'의 중세 형태 \'애셔\'에서 \'셔\'는 지점의 의미를 나타냈다.', '중세 국어 \'에셔\'가 주격 조사로 쓰일 수 있었던 이유는 \'에셔\' 앞에 유정 명사가 오기 때문이다.'], 1,
    ['① 옳다. 중세 "애/에/예"는 현대 "에"와 "에서"의 쓰임을 모두 지녔으므로 앞 명사가 공간의 의미를 나타낼 수 있었다.', '② 옳지 않다. (1)처럼 "서울에/서울에서"가 모두 가능하다.', '③ 옳지 않다. 주격 조사로 쓰인 것은 "에셔" 계열이다.', '④ 옳지 않다. "셔"는 "이셔"에서 온 것으로 공간 속에 있음을 나타낸다.', '⑤ 옳지 않다. "에셔" 앞에는 공간·집단 명사가 오고 유정 명사는 오지 않는다.'],
    passage=PSG_20, grp='N-20', ref=[4], core='에 = [지점], 에서 = [공간]. 에서가 주격으로 쓰이려면 앞에 공간·집단 명사.')

add('N-045', 'Ⅱ-D', '중세 국어의 격 조사', '상', S % '2020학년도 9월 모의평가 12번',
    p('윗글을 바탕으로 〈보기〉를 이해한 내용으로 적절하지 <u>않은</u> 것은?') +
    bogi(['<b>현대 국어</b> ㉠ 그 지역에서 공룡 화석이 발견되었다. ㉡ 정부에서 홍수 대책안을 발표하였다. ㉢ 할머니께서 저녁 늦게 식사를 하셨다.', '<b>중세 국어</b> ㉣ 一物이라도 그위예셔 다 아ᄉᆞᆷ 슬노라 [물건 하나라도 관청에서 다 빼앗음을 슬퍼하노라] ㉤ 부텨씌셔 十二部經이 나시고 [부처님으로부터 12부경이 나오고]']),
    ['㉠은 공간을 의미하는 \'그 지역\'에 주격 조사 \'에서\'가 결합한 것이군.', '㉡은 집단을 의미하는 \'정부\'에 주격 조사 \'에서\'가 결합한 것이군.', '㉢은 높임의 유정 명사 \'할머니\'에 주격 조사 \'께서\'가 결합한 것이군.', '㉣은 \'그위\'에 주격 조사 \'예셔\'가 결합한 것이군.', '㉤은 높임의 유정 명사 \'부텨\'에 부사격 조사 \'씌셔\'가 결합한 것이군.'], 1,
    ['① 적절하지 않다. ㉠의 "그 지역에서"는 공룡 화석이 발견된 장소를 나타내는 부사격 조사이다. 주격 조사는 구성원으로 이루어진 집단 명사 뒤에 쓰인다.', '② 적절하다. "정부"는 집단이므로 "에서"가 주격 조사이다.', '③ 적절하다. "께서"는 높임의 주격 조사이다.', '④ 적절하다. "그위(관청)"는 집단이며 "예셔"가 주격 조사이다.', '⑤ 적절하다. "씌셔"는 "…으로부터"의 부사격 조사이다.'],
    passage=PSG_20, grp='N-20', ref=[4], core='주격 "에서"는 집단·기관 명사 뒤. 장소(공간)를 나타내면 부사격이다.')

# ---------------------------------------------------------------- [22~23] 2019 수능 12~13
PSG_22 = ('<p class="hd"><b>[22~23]</b> 다음 글을 읽고 물음에 답하시오. <small>(원문 요약)</small></p>'
          '<p>\'ㄹ\' 받침 명사 \'발\', \'솔\', \'이틀\'이 <b>㉠</b>\'발가락\', <b>㉡</b>\'소나무\', <b>㉢</b>\'이튿날\'에서는 받침 \'ㄹ\'의 모습이 일관되지 않다. \'소나무\'는 \'ㄹ\'이 탈락하고, \'이튿날\'은 \'ㄷ\'으로 나타난다. 현대 국어에는 \'ㄹ→ㄷ\' 교체나 명사 + 명사에서의 \'ㄹ\' 탈락 규칙이 없어서 현대 규칙만으로는 설명할 수 없다.</p>'
          '<p>\'발가락\'은 중세에 대부분 \'밠 가락\'이었다. \'ㅅ\'은 관형격 조사로 쓰여 구로 파악되었다(\'밠 엄지 가락\'). 이후 \'ㅅ\'은 관형격 조사 기능을 잃고 합성어 내부의 사이시옷으로만 흔적이 남아 현대 \'발가락[발까락]\'이 되었다.</p>'
          '<p><b>[A]</b> \'소나무\'는 중세 명사 \'솔\'에 \'나모\'(나무)가 결합하며 \'ㄹ\'이 탈락한 합성어 \'소나모\'이다. 중세에는 명사 + 명사 합성어에서 \'ㄴ, ㄷ, ㅅ, ㅈ\' 등으로 시작하는 명사 앞에서 받침 \'ㄹ\'이 탈락하는 규칙이 있었다.</p>'
          '<p>\'이튿날\'은 중세 자립 명사 \'이틀\'과 \'날\' 사이에 관형격 \'ㅅ\'이 결합한 \'이틄 날\'로 많이 나타난다(\'이틄 밤\', \'이틄 길\'의 \'ㅅ\'과 같음). \'이틋 날\'로도 나타나다가 근대에 \'ㄹ\'이 탈락한 합성어 \'이틋날\'로 굳어졌다. \'ㅅ\'이 관형격 기능을 잃고 받침 \'ㅅ\'과 \'ㄷ\'의 발음이 구분되지 않게 되었다. 「한글 맞춤법」은 \'이튿날\'의 표기를 "끝소리가 \'ㄹ\'인 말과 딴 말이 어울릴 적에 \'ㄹ\' 소리가 \'ㄷ\' 소리로 나는 것"으로 보아 \'이튿날\'로 적게 하였다. 그러나 이때의 \'ㄷ\'은 \'ㄹ\'이 변한 것으로 설명되지 않으므로 중세 \'믇 사롬\'에서 온 \'뭇사람\'처럼 \'ㅅ\'으로 적는 것이 국어의 변화 과정을 고려한 관점에 부합한다고 할 수 있다. <b>[A 끝]</b></p>')

add('N-046', 'Ⅱ-D', '중세 국어의 음운 변화', '상', S % '2019학년도 대학수학능력시험 12번',
    p('윗글을 참고할 때, ㉠~㉢과 같이 \'이러한 차이\'를 보이는 예를 〈보기〉에서 각각 하나씩 찾아 그 순서대로 제시한 것은?') + bogi(['무술(물+술), 낟알(낟+알), 섣달(설+달), 쌀가루(쌀+가루), 솔방울(솔+방울), 푸나무(풀+나무)']),
    ['솔방울, 무술, 낟알', '솔방울, 푸나무, 섣달', '푸나무, 무술, 섣달', '쌀가루, 푸나무, 낟알', '쌀가루, 솔방울, 섣달'], 2,
    ['㉠(발가락: ㄹ이 유지되고 ㅅ 흔적으로 된소리): 솔방울(솔 + 방울 → [솔빵울]) · 쌀가루. ㉡(소나무: ㄹ 탈락): 푸나무(풀 + 나무), 무술(물 + 술). ㉢(이튿날: ㄹ → ㄷ): 섣달(설 + 달). 낟알은 원래 ㄷ 받침이다.', '→ ㉠ 솔방울, ㉡ 푸나무, ㉢ 섣달 = ②.'],
    passage=PSG_22, grp='N-22', ref=[2], core='합성어의 받침 ㄹ: 유지(발가락), 탈락(소나무), ㄷ으로 교체(이튿날). 중세 관형격 ㅅ과 ㄹ 탈락 규칙으로 설명한다.')

add('N-047', 'Ⅱ-D', '중세 국어의 음운 변화', '상', S % '2019학년도 대학수학능력시험 13번',
    p('[A]를 바탕으로 〈보기〉의 \'자료\'를 탐구한 내용으로 적절하지 <u>않은</u> 것은?') +
    bogi(['<b>탐구 주제</b> \'숟가락\'은 \'젓가락\'과 달리 첫 글자의 받침이 \'ㄷ\'인 이유는?', '<b>자료</b> 중세: 술 자ᄇᆞ며 져 녿ᄂᆞ니 [숟가락 잡으며 젓가락 놓으니], 숤 근 [숟가락의 끝], 졋 가락 근 [젓가락 끝], 수져 [수저], 믈 [무리], 믇 사ᄅᆞᆷ [뭇사람] / 근대: 숫가락 장수, 뭇사ᄅᆞᆷ / 현대: *술로 밥을 뜨다(비문), 숟가락으로 밥을 뜨다, 밥 한 술']),
    ['중세 국어의 \'술\'과 \'져\'는 \'이틀\'처럼 자립 명사라는 점에서 현대 국어의 \'술\'과 차이가 있다.', '중세 국어 \'술\'과 \'져\'의 결합에서 \'ㄹ\'이 탈락한 합성어가 현대 국어 \'수저\'로 이어졌다.', '중세 국어의 \'술\'과 \'져\'는 명사를 수식할 때 \'이틀\'이나 \'믈\'과 같이 모두 관형격 \'ㅅ\'과 결합할 수 있었다.', '근대 국어 \'숫가락\'이 현대 국어 \'숟가락\'으로 적히는 것은 국어의 변화 과정을 고려한 관점에 부합하지 않는다는 점에서 \'이튿날\'과 같다.', '현대 국어 \'숟가락\'과 \'뭇사람\'의 첫 글자 받침이 다른 이유는 중세 국어 \'숤\'과 \'믇\'이 현대로 오면서 \'ㄹ\' 탈락 후 남은 \'ㅅ\'의 발음이 서로 달랐기 때문이다.'], 5,
    ['① 옳다. 중세 "술"은 자립 명사였고, 현대 "술"(밥 한 술)은 의존 명사이다.', '② 옳다. "술 + 져 → 수저"에서 ㄹ이 탈락했다.', '③ 옳다. "숤 근", "졋 가락 근", "이틄 날", "믈"(무리)에서 보듯 관형격 ㅅ이 결합했다.', '④ 옳다. 중세 ㅅ에서 온 "숫가락"을 ㄹ → ㄷ 규정으로 "숟가락"이라 적는 것은 "이튿날"과 같은 방식이다.', '⑤ 옳지 않다. "숟가락"은 "ㄹ이 ㄷ으로 나는 것"으로 보아 ㄷ을 적었고(제29항), "뭇사람"은 중세 "믇 사ᄅᆞᆷ"의 ㅅ을 적은 것이다. 남은 ㅅ의 발음이 서로 달라서가 아니다.'],
    passage=PSG_22, grp='N-22', ref=[2], core='ㄹ → ㄷ 규정(제29항)은 "ㄹ이 변한 것"이 아니라 중세 관형격 ㅅ에서 온 것이어서 변화 과정과 맞지 않는 면이 있다.')
